/* eslint-disable react-hooks/static-components */
 
"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
import DuoTranslate from "../DuoMCB/DuoTranslate";

const SectionHeader = ({ icon, title }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 12, fontSize: 22, fontWeight: 700, color: "#0B4F5C", marginBottom: 20, paddingBottom: 12, borderBottom: "2px solid #f0f0f0" }}>
    <span>{icon}</span><span>{title}</span>
  </div>
);

export default function Lesson6_HamSoVaDoThi() {
    const [lang, setLang] = useState("vi");
    const [revealedAnswers, setRevealedAnswers] = useState({});
    const [gameMode, setGameMode] = useState("mc");
  
    const [mcIndex, setMcIndex] = useState(0);
    const [mcSelected, setMcSelected] = useState(null);
    const [mcScore, setMcScore] = useState(0);
    const [mcDone, setMcDone] = useState(false);
    const [mcHistory, setMcHistory] = useState([]);
  
    const [tfIndex, setTfIndex] = useState(0);
    const [tfFlipped, setTfFlipped] = useState(false);
    const [tfScore, setTfScore] = useState(0);
    const [tfDone, setTfDone] = useState(false);
    const [tfHistory, setTfHistory] = useState([]);
  
    const [fillAnswers, setFillAnswers] = useState({});
    const [fillChecked, setFillChecked] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const els = document.querySelectorAll("[data-reveal]");
    els.forEach((el) => {
      if (el.hasAttribute("data-reveal-stagger")) {
        const stagger = parseInt(el.getAttribute("data-stagger") || "80", 10);
        Array.from(el.children).forEach((child, i) => {
          child.style.opacity = "0";
          child.style.transform = "translateY(24px) scale(0.97)";
          child.style.transition = `opacity 0.5s cubic-bezier(.2,.8,.2,1) ${i * stagger}ms, transform 0.45s cubic-bezier(.2,.8,.2,1) ${i * stagger}ms`;
        });
      }
    });
    const obs = new IntersectionObserver(
      (entries, observer) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const el = entry.target;
            if (el.hasAttribute("data-reveal-stagger")) {
              const stagger = parseInt(el.getAttribute("data-stagger") || "80", 10);
              Array.from(el.children).forEach((child, i) => {
                setTimeout(() => { child.style.opacity = "1"; child.style.transform = "translateY(0) scale(1)"; }, i * stagger);
              });
            }
            el.classList.add("visible");
            observer.unobserve(el);
          }
        });
      },
      { threshold: 0.12 }
    );
    els.forEach((el) => obs.observe(el));
    return () => obs.disconnect();
  }, []);

  const t = (vi, en) => (lang === "vi" ? vi : en);
  const toggleAnswer = (id) => setRevealedAnswers((p) => ({ ...p, [id]: !p[id] }));
  const scrollTo = (id) => { const el = document.getElementById(id); if (el) el.scrollIntoView({ behavior: "smooth", block: "start" }); };

  const mcQuestions = [
    {
      q: t("Tập xác định của hàm số y = 1/(x-2) là?", "What is the domain of the function y = 1/(x-2)?"),
      options: ["R", "R \\ {0}", "R \\ {2}", "(2, +∞)"],
      answer: 2,
      explain: t("Mẫu thức phải khác 0: x - 2 ≠ 0 → x ≠ 2.", "Denominator must be non-zero: x - 2 ≠ 0 → x ≠ 2.")
    },
    {
      q: t("Hàm số y = x² là hàm số đồng biến trên khoảng nào?", "On which interval is the function y = x² increasing?"),
      options: ["(-∞, +∞)", "(-∞, 0)", "(0, +∞)", "R \\ {0}"],
      answer: 2,
      explain: t("Với x > 0, khi x tăng thì x² tăng → đồng biến trên (0, +∞).", "For x > 0, as x increases, x² increases → increasing on (0, +∞).")
    },
    {
      q: t("Điểm nào sau đây thuộc đồ thị hàm số y = 2x + 1?", "Which point belongs to the graph of y = 2x + 1?"),
      options: ["(0, 0)", "(1, 2)", "(1, 3)", "(2, 4)"],
      answer: 2,
      explain: t("Thay x=1 vào: y = 2(1)+1 = 3. Vậy điểm (1,3) thuộc đồ thị.", "Substitute x=1: y = 2(1)+1 = 3. So (1,3) is on the graph.")
    }
  ];

  const tfCards = [
    { stmt: t("Mọi quy tắc cho tương ứng mỗi x thuộc D với duy nhất một y thuộc R đều là hàm số.", "Every rule that assigns each x in D to exactly one y in R is a function."), answer: true, explain: t("ĐÚNG — Đây là định nghĩa cơ bản của hàm số.", "TRUE — This is the basic definition of a function.") },
    { stmt: t("Hàm số y = |x| là hàm số lẻ.", "The function y = |x| is an odd function."), answer: false, explain: t("SAI — y = |x| là hàm số chẵn vì |-x| = |x|.", "FALSE — y = |x| is an even function because |-x| = |x|.") },
    { stmt: t("Đồ thị hàm số chẵn nhận trục tung Oy làm trục đối xứng.", "The graph of an even function is symmetric about the y-axis (Oy)."), answer: true, explain: t("ĐÚNG — f(-x) = f(x) tạo nên tính đối xứng qua Oy.", "TRUE — f(-x) = f(x) creates symmetry across the y-axis.") }
  ];

  const fillQuestions = [
    { id: "f1", template: t("Tập hợp các giá trị của x để f(x) có nghĩa gọi là tập ___.", "The set of x-values for which f(x) is defined is called the ___."), answer: "xác định", altAnswers: ["domain", "tap xac dinh"], hint: t("Kí hiệu là D.", "Symbolized as D.") },
    { id: "f2", template: t("Hàm số f(x) gọi là ___ trên K nếu với mọi x1 < x2 thì f(x1) < f(x2).", "Function f(x) is ___ on K if for all x1 < x2, then f(x1) < f(x2)."), answer: "đồng biến", altAnswers: ["increasing", "dong bien"], hint: t("Giá trị y tăng cùng với x.", "Y increases as X increases.") }
  ];

  // Game Logic Handlers (Same as your sample)
  const handleMcSelect = (i) => {
    if (mcSelected !== null) return;
    setMcSelected(i);
    const correct = i === mcQuestions[mcIndex].answer;
    if (correct) setMcScore((s) => s + 1);
    setMcHistory((h) => [...h, { q: mcIndex, selected: i, correct }]);
  };
  const handleMcNext = () => { if (mcIndex + 1 >= mcQuestions.length) setMcDone(true); else { setMcIndex((i) => i + 1); setMcSelected(null); } };
  const resetMc = () => { setMcIndex(0); setMcSelected(null); setMcScore(0); setMcDone(false); setMcHistory([]); };

  const handleTfAnswer = (ans) => {
    if (tfFlipped) return;
    setTfFlipped(true);
    const correct = ans === tfCards[tfIndex].answer;
    if (correct) setTfScore((s) => s + 1);
    setTfHistory((h) => [...h, { q: tfIndex, given: ans, correct }]);
  };
  const handleTfNext = () => { if (tfIndex + 1 >= tfCards.length) setTfDone(true); else { setTfIndex((i) => i + 1); setTfFlipped(false); } };
  const resetTf = () => { setTfIndex(0); setTfFlipped(false); setTfScore(0); setTfDone(false); setTfHistory([]); };

  const checkFill = (id) => {
    const q = fillQuestions.find((q) => q.id === id);
    const raw = (fillAnswers[id] || "").toLowerCase().trim().replace(/\s/g, "");
    const answers = [q.answer, ...(q.altAnswers || [])].map(a => a.toLowerCase().replace(/\s/g, ""));
    return answers.includes(raw);
  };
  const fillScore = fillChecked ? fillQuestions.filter(q => checkFill(q.id)).length : null;

  const tabs = [
    ["tomTat", "📚", t("Tóm Tắt", "Summary")],
    ["congThuc", "📐", t("Công Thức", "Key Formulas")],
    ["baiTapTongHop", "✏️", t("Bài Tập TH", "Mixed Exercises")],
    ["miniGame", "🎮", t("Mini Game", "Mini Game")],
  ];

  const SectionHeader = ({ icon, title }) => (
    <div style={{ display: "flex", alignItems: "center", gap: 12, fontSize: 22, fontWeight: 700, color: "#0B4F5C", marginBottom: 20, paddingBottom: 12, borderBottom: "2px solid #f0f0f0" }}>
      <span>{icon}</span><span>{title}</span>
    </div>
  );

  const ResultSummary = ({ items, onReset, scoreLabel }) => (
    <div>
      <div style={{ textAlign: "center", marginBottom: 24 }}>
        <div style={{ fontSize: 48, marginBottom: 8 }}>
          {items.filter(i => i.correct).length === items.length ? "🏆" : items.filter(i => i.correct).length >= items.length * 0.6 ? "👍" : "💪"}
        </div>
        <div style={{ fontSize: 26, fontWeight: 700, color: "#0B4F5C" }}>
          {items.filter(i => i.correct).length} / {items.length}
        </div>
        <div style={{ color: "#777", fontSize: 16, marginTop: 4 }}>{scoreLabel}</div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 24 }}>
        {items.map((item, idx) => (
          <div key={idx} style={{ padding: "14px 18px", borderRadius: 10, background: item.correct ? "#eafaf1" : "#fdf2f2", border: `1px solid ${item.correct ? "#a9dfbf" : "#f1948a"}` }}>
            <div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}>
              <span style={{ fontSize: 18, flexShrink: 0 }}>{item.correct ? "✅" : "❌"}</span>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 15, fontWeight: 600, color: "#333", marginBottom: 4 }}>{t("Câu", "Q")} {idx + 1}: {item.qText}</div>
                {!item.correct && <div style={{ fontSize: 14, color: "#922b21" }}>{t("Đáp án đúng:", "Correct answer:")} <strong>{item.correctText}</strong></div>}
                {item.yourText && !item.correct && <div style={{ fontSize: 14, color: "#777" }}>{t("Bạn chọn:", "You answered:")} {item.yourText}</div>}
              </div>
            </div>
          </div>
        ))}
      </div>
      <div style={{ textAlign: "center" }}>
        <button onClick={onReset} style={{ padding: "12px 32px", background: "black", color: "white", border: "none", borderRadius: 8, fontWeight: 600, fontSize: 15, cursor: "pointer" }}>
          🔄 {t("Chơi lại", "Play Again")}
        </button>
      </div>
    </div>
  );

  const mcResultItems = mcHistory.map((h) => ({ correct: h.correct, qText: mcQuestions[h.q].q, correctText: mcQuestions[h.q].options[mcQuestions[h.q].answer], yourText: mcQuestions[h.q].options[h.selected] }));
  const tfResultItems = tfHistory.map((h) => ({ correct: h.correct, qText: tfCards[h.q].stmt, correctText: tfCards[h.q].answer ? t("ĐÚNG", "TRUE") : t("SAI", "FALSE"), yourText: h.given ? t("ĐÚNG", "TRUE") : t("SAI", "FALSE") }));
  const fillResultItems = fillChecked ? fillQuestions.map((q) => ({ correct: checkFill(q.id), qText: q.template, correctText: q.answer, yourText: fillAnswers[q.id] || t("(bỏ trống)", "(blank)") })) : [];

  return (
    <div style={{ width: "100%", background: "#ffffff", display: "flex", justifyContent: "center" }}>
      <div style={{ width: "1200px", maxWidth: "95%", color: "black", paddingTop: 60, paddingBottom: 80 }}>
        
        <header className="reveal" data-reveal style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 40 }}>
          <div>
            <div style={{ fontWeight: "bold", fontSize: 20, color: "#0B4F5C" }}>{t("Chương III · Hàm Số và Đồ Thị", "Chapter III · Functions and Graphs")}</div>
            <div style={{ fontSize: 28, fontWeight: 600 }}>{t("Bài 1: Hàm số và tập xác định", "Lesson 1: Functions and Domain")}</div>
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={() => setLang("vi")} style={{ background: lang === "vi" ? "black" : "#eee", color: lang === "vi" ? "white" : "black", border: "none", padding: "10px 15px", borderRadius: 8, cursor: "pointer" }}>VN</button>
            <button onClick={() => setLang("en")} style={{ background: lang === "en" ? "black" : "#eee", color: lang === "en" ? "white" : "black", border: "none", padding: "10px 15px", borderRadius: 8, cursor: "pointer" }}>EN</button>
          </div>
        </header>

        <nav style={{ position: "sticky", top: 10, zIndex: 100, background: "white", padding: "10px 0", marginBottom: 40, display: "flex", gap: 10, flexWrap: "wrap", borderBottom: "1px solid #eee" }}>
          {tabs.map(([id, icon, label]) => (
            <button key={id} onClick={() => scrollTo(id)} style={{ padding: "8px 12px", borderRadius: 8, border: "1px solid #ddd", background: "white", cursor: "pointer", fontSize: 14 }}>{icon} {label}</button>
          ))}
        </nav>

        {/* SECTION 1: KHỞI ĐỘNG */}
        <section id="khoiDong" style={{ marginBottom: 60 }}>
          <SectionHeader icon="🚀" title={t("Khởi động", "Warm-Up")} />
          <div style={{ padding: 25, background: "#f9f9f9", borderRadius: 15 }}>
            <p style={{ fontSize: 16, lineHeight: 1.8 }}>
              {t("Trong thực tế, nhiều đại lượng thay đổi phụ thuộc vào nhau. Ví dụ: Quãng đường s đi được phụ thuộc vào thời gian t, hay tiền điện phụ thuộc vào lượng điện tiêu thụ.", 
                "In reality, many quantities depend on each other. For example, distance s depends on time t, or electricity cost depends on consumption.")}
            </p>
          </div>
        </section>

        {/* SECTION 2: ĐỊNH NGHĨA */}
        <section id="khai1" style={{ marginBottom: 60 }}>
          <SectionHeader icon="📖" title={t("1. Định nghĩa hàm số", "1. Definition of a Function")} />
          <div className="reveal" data-reveal style={{ padding: 25, border: "2px solid #0B4F5C", borderRadius: 15 }}>
            <p style={{ fontWeight: 600 }}>{t("Định nghĩa:", "Definition:")}</p>
            <p>{t("Cho tập hợp khác rỗng D ⊂ R. Nếu với mỗi giá trị x ∈ D có duy nhất một giá trị y ∈ R tương ứng thì ta có một hàm số.", 
                 "Let D be a non-empty subset of R. If for each value x ∈ D there is exactly one corresponding value y ∈ R, we have a function.")}</p>
            <ul style={{ marginTop: 15 }}>
              <li>{t("x gọi là biến số.", "x is the independent variable.")}</li>
              <li>{t("D gọi là tập xác định.", "D is the domain.")}</li>
            </ul>
          </div>
        </section>

        {/* SECTION 3: SỰ BIẾN THIÊN */}
        <section id="khai3" style={{ marginBottom: 60 }}>
          <SectionHeader icon="🔄" title={t("2. Sự biến thiên của hàm số", "2. Monotonicity of Functions")} />
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
            <div style={{ padding: 20, background: "#eafaf1", borderRadius: 12 }}>
              <h4 style={{ color: "#1e8449" }}>📈 {t("Hàm số đồng biến (Tăng)", "Increasing Function")}</h4>
              <p style={{ fontSize: 14 }}>{t("Khi x tăng thì y tăng.", "As x increases, y increases.")}</p>
            </div>
            <div style={{ padding: 20, background: "#fdf2f2", borderRadius: 12 }}>
              <h4 style={{ color: "#922b21" }}>📉 {t("Hàm số nghịch biến (Giảm)", "Decreasing Function")}</h4>
              <p style={{ fontSize: 14 }}>{t("Khi x tăng thì y giảm.", "As x increases, y decreases.")}</p>
            </div>
          </div>
        </section>

        {/* MINI GAME */}
        <section id="miniGame" style={{ marginBottom: 60 }}>
          <SectionHeader icon="🎮" title={t("Mini Game Kiểm Tra", "Knowledge Check")} />
          <div style={{ display: "flex", gap: 10, marginBottom: 20 }}>
            {["mc", "tf", "fill"].map(mode => (
              <button key={mode} onClick={() => setGameMode(mode)} style={{ padding: "10px 20px", borderRadius: 8, background: gameMode === mode ? "black" : "#eee", color: gameMode === mode ? "white" : "black", border: "none", cursor: "pointer" }}>
                {mode.toUpperCase()}
              </button>
            ))}
          </div>

          <div style={{ padding: 30, background: "#f9f9f9", borderRadius: 15, boxShadow: "0 4px 12px rgba(0,0,0,0.05)" }}>
            {gameMode === "mc" && !mcDone && (
              <div>
                <p style={{ fontSize: 18, fontWeight: 600 }}>{mcQuestions[mcIndex].q}</p>
                <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 20 }}>
                  {mcQuestions[mcIndex].options.map((opt, i) => (
                    <button key={i} onClick={() => handleMcSelect(i)} style={{ padding: 15, textAlign: "left", borderRadius: 10, border: "1px solid #ddd", background: mcSelected === i ? "#eee" : "white", cursor: "pointer" }}>
                      {opt}
                    </button>
                  ))}
                </div>
                {mcSelected !== null && <button onClick={handleMcNext} style={{ marginTop: 20, padding: "10px 20px", background: "black", color: "white", border: "none", borderRadius: 8 }}>{t("Tiếp theo", "Next")}</button>}
              </div>
            )}
            {gameMode === "mc" && mcDone && <ResultSummary items={mcHistory} onReset={() => {setMcIndex(0); setMcDone(false); setMcSelected(null); setMcHistory([]);}} />}
            
            {/* Logic for TF and Fill follows the same pattern as your sample */}
            {gameMode === "tf" && (
            <div style={{ padding: 24, borderRadius: 10, background: "#f9f9f9", boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
              {!tfDone ? (
                <>
                  <div style={{ color: "#777", fontSize: 15, marginBottom: 14 }}>{t("Thẻ", "Card")} {tfIndex + 1}/{tfCards.length} · {t("Điểm:", "Score:")} {tfScore}</div>
                  <article style={{ background: "white", borderRadius: 10, padding: 24, marginBottom: 20, textAlign: "center", boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
                    <div style={{ fontSize: 18, lineHeight: 1.7, marginBottom: 24 }}>{tfCards[tfIndex].stmt}</div>
                    {!tfFlipped ? (
                      <div style={{ display: "flex", gap: 16, justifyContent: "center" }}>
                        <button onClick={() => handleTfAnswer(true)} style={{ padding: "12px 36px", background: "#eafaf1", color: "#1e8449", border: "2px solid #1e8449", borderRadius: 8, fontWeight: 700, fontSize: 16, cursor: "pointer" }}>✅ {t("ĐÚNG", "TRUE")}</button>
                        <button onClick={() => handleTfAnswer(false)} style={{ padding: "12px 36px", background: "#fdf2f2", color: "#922b21", border: "2px solid #922b21", borderRadius: 8, fontWeight: 700, fontSize: 16, cursor: "pointer" }}>❌ {t("SAI", "FALSE")}</button>
                      </div>
                    ) : (
                      <><div style={{ padding: "12px 16px", background: "#f9f9f9", borderRadius: 8, fontSize: 15, color: "#555", textAlign: "left", marginBottom: 14, boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>💬 {tfCards[tfIndex].explain}</div><button onClick={handleTfNext} style={{ padding: "12px 28px", background: "black", color: "white", border: "none", borderRadius: 8, fontWeight: 600, fontSize: 15, cursor: "pointer" }}>{tfIndex + 1 < tfCards.length ? t("Thẻ tiếp ▶", "Next ▶") : t("Xem kết quả", "See Results")}</button></>
                    )}
                  </article>
                </>
              ) : (
                <ResultSummary items={tfResultItems} onReset={resetTf} scoreLabel={tfScore === tfCards.length ? t("Xuất sắc! 🎉", "Perfect! 🎉") : t("Cố gắng thêm! 💪", "Keep going! 💪")} />
              )}
            </div>
          )}
           {gameMode === "fill" && (
            <div style={{ padding: 24, borderRadius: 10, background: "#f9f9f9", boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
              {!fillChecked ? (
                <>
                  <div style={{ fontSize: 18, fontWeight: 600, marginBottom: 20 }}>{t("Điền câu trả lời vào chỗ trống", "Fill in each blank")}</div>
                  {fillQuestions.map((q, qi) => (
                    <div key={q.id} style={{ marginBottom: 24 }}>
                      <div style={{ fontSize: 15, color: "#777", marginBottom: 6 }}>{t("Câu", "Q")} {qi + 1}</div>
                      <div style={{ fontSize: 16, lineHeight: 1.7, marginBottom: 10 }}>{q.template}</div>
                      <input value={fillAnswers[q.id] || ""} onChange={(e) => setFillAnswers((p) => ({ ...p, [q.id]: e.target.value }))} placeholder={t("Nhập đáp án...", "Enter answer...")} style={{ width: "100%", padding: "12px 16px", borderRadius: 8, fontSize: 15, outline: "none", border: "1px solid #ddd", background: "white", boxShadow: "0 4px 12px rgba(0,0,0,0.1)", boxSizing: "border-box" }} />
                    </div>
                  ))}
                  <button onClick={() => setFillChecked(true)} style={{ padding: "12px 32px", background: "black", color: "white", border: "none", borderRadius: 8, fontWeight: 600, fontSize: 15, cursor: "pointer" }}>{t("Kiểm tra", "Check Answers")}</button>
                </>
              ) : (
                <ResultSummary items={fillResultItems} onReset={() => { setFillAnswers({}); setFillChecked(false); }} scoreLabel={fillScore === fillQuestions.length ? t("Xuất sắc! 🎉", "Perfect! 🎉") : fillScore >= 2 ? t("Tốt lắm! 👍", "Well done! 👍") : t("Cố gắng thêm! 💪", "Keep going! 💪")} />
              )}
            </div>
          )}
          </div>
        </section>

        <DuoTranslate />
        <footer style={{ textAlign: "center", color: "#aaa", marginTop: 80 }}>
          Toán 10 · Chân Trời Sáng Tạo · {t("Chương III / Bài 1", "Chapter III / Lesson 1")}
        </footer>

        <style>{`
          .reveal { opacity: 0; transform: translateY(20px); transition: all 0.6s ease-out; }
          .reveal.visible { opacity: 1; transform: translateY(0); }
        `}</style>
      </div>
    </div>
  );
}